import javax.imageio.ImageReader;
import javax.imageio.stream.ImageInputStream;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;

public class BMPImageReaderReadTests {

    private static byte[] minimalBmpBytes() {
        // Construct a minimal 1x1 24-bit BMP (BI_RGB) with a black pixel.
        // File header (14 bytes) + DIB header (40 bytes) + 4 bytes pixel data.
        ByteBuffer bb = ByteBuffer.allocate(14 + 40 + 4);
        bb.order(ByteOrder.LITTLE_ENDIAN);

        // BMP File header
        bb.put((byte) 0x42); // 'B'
        bb.put((byte) 0x4D); // 'M'
        bb.putInt(58);       // File size
        bb.putShort((short)0); // Reserved1
        bb.putShort((short)0); // Reserved2
        bb.putInt(54);       // Offset to pixel data (14 + 40)

        // DIB header (BITMAPINFOHEADER)
        bb.putInt(40);         // DIB header size
        bb.putInt(1);          // Width
        bb.putInt(1);          // Height
        bb.putShort((short)1); // Planes
        bb.putShort((short)24);// BitCount
        bb.putInt(0);          // Compression (BI_RGB)
        bb.putInt(4);          // ImageSize
        bb.putInt(0);          // XpixelsPerMeter
        bb.putInt(0);          // YpixelsPerMeter
        bb.putInt(0);          // ColorsUsed
        bb.putInt(0);          // ImportantColors

        // Pixel data: B, G, R, padding (0,0,0)
        bb.put((byte)0); // Blue
        bb.put((byte)0); // Green
        bb.put((byte)0); // Red
        bb.put((byte)0); // Padding

        return bb.array();
    }

    @Test
    void testReadUncompressed24Bit1x1BlackPixel() throws Exception {
        byte[] data = minimalBmpBytes();
        ImageInputStream iis = ImageIO.createImageInputStream(new ByteArrayInputStream(data));

        BMPImageReader reader = new BMPImageReader();
        reader.setInput(iis, true, false);

        BufferedImage image = reader.read(0, (ImageReadParam) null);

        Assertions.assertNotNull(image, "Expected non-null image");
        Assertions.assertEquals(1, image.getWidth(), "Unexpected width");
        Assertions.assertEquals(1, image.getHeight(), "Unexpected height");

        int rgb = image.getRGB(0, 0);
        Assertions.assertEquals(0xFF000000, rgb, "Expected opaque black pixel @ (0,0)");
    }

    @Test
    void testReadInvalidImageIndexThrowsIndexOutOfBounds() throws Exception {
        byte[] data = minimalBmpBytes();
        ImageInputStream iis = ImageIO.createImageInputStream(new ByteArrayInputStream(data));

        BMPImageReader reader = new BMPImageReader();
        reader.setInput(iis, true, false);

        Assertions.assertThrows(IndexOutOfBoundsException.class, () -> {
            reader.read(1, (ImageReadParam) null);
        });
    }
}

package com.twelvemonkeys.imageio.plugins.bmp;

import org.junit.jupiter.api.Test;

import javax.imageio.ImageReadParam;
import javax.imageio.stream.MemoryCacheImageInputStream;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.IOException;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

class BMPImageReaderReadTests {
    @Test
    void readsBottomUpBmpWithRowPaddingAndBgrPixels() throws IOException {
        BMPImageReader reader = new BMPImageReader();

        try (MemoryCacheImageInputStream input =
                     new MemoryCacheImageInputStream(new ByteArrayInputStream(twoByTwoBmp()))) {
            reader.setInput(input);

            BufferedImage image = reader.read(0, null);

            assertEquals(2, image.getWidth());
            assertEquals(2, image.getHeight());

            // BMP stores scanlines bottom-up and pixels in blue-green-red order.
            assertEquals(0xffff0000, image.getRGB(0, 0));
            assertEquals(0xff00ff00, image.getRGB(1, 0));
            assertEquals(0xff0000ff, image.getRGB(0, 1));
            assertEquals(0xffffffff, image.getRGB(1, 1));
        }
        finally {
            reader.dispose();
        }
    }

    @Test
    void rejectsAnImageIndexBeyondTheSingleBmpImage() throws IOException {
        BMPImageReader reader = new BMPImageReader();

        try (MemoryCacheImageInputStream input =
                     new MemoryCacheImageInputStream(new ByteArrayInputStream(twoByTwoBmp()))) {
            reader.setInput(input);

            assertThrows(IndexOutOfBoundsException.class, () -> reader.read(1, null));
        }
        finally {
            reader.dispose();
        }
    }

    private static byte[] twoByTwoBmp() {
        byte[] bmp = new byte[70];

        bmp[0] = 'B';
        bmp[1] = 'M';
        putInt(bmp, 2, bmp.length);
        putInt(bmp, 10, 54);

        putInt(bmp, 14, 40);
        putInt(bmp, 18, 2);
        putInt(bmp, 22, 2);
        putShort(bmp, 26, 1);
        putShort(bmp, 28, 24);
        putInt(bmp, 30, 0);
        putInt(bmp, 34, 16);
        putInt(bmp, 38, 2835);
        putInt(bmp, 42, 2835);

        int offset = 54;

        // Bottom scanline: blue, then white, followed by two bytes of padding.
        putBgr(bmp, offset, 0, 0, 255);
        putBgr(bmp, offset + 3, 255, 255, 255);
        offset += 8;

        // Top scanline: red, then green, followed by two bytes of padding.
        putBgr(bmp, offset, 255, 0, 0);
        putBgr(bmp, offset + 3, 0, 255, 0);

        return bmp;
    }

    private static void putBgr(byte[] data, int offset, int red, int green, int blue) {
        data[offset] = (byte) blue;
        data[offset + 1] = (byte) green;
        data[offset + 2] = (byte) red;
    }

    private static void putShort(byte[] data, int offset, int value) {
        data[offset] = (byte) value;
        data[offset + 1] = (byte) (value >>> 8);
    }

    private static void putInt(byte[] data, int offset, int value) {
        data[offset] = (byte) value;
        data[offset + 1] = (byte) (value >>> 8);
        data[offset + 2] = (byte) (value >>> 16);
        data[offset + 3] = (byte) (value >>> 24);
    }
}

