package com.twelvemonkeys.imageio.plugins.jpeg;

import org.junit.jupiter.api.Test;
import javax.imageio.IIOException;
import javax.imageio.stream.ImageInputStream;
import javax.imageio.ImageIO;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

public class JPEGLosslessDecoderDecodeTests {

    @Test
    void testDecodeThrowsWhenFirstTwoBytesNotSOI() throws IOException {
        // Arrange: prepare a minimal non-SOI JPEG prefix and an empty segment list
        List<Segment> segments = new ArrayList<>();
        byte[] badPrefix = new byte[] { (byte)0x12, (byte)0x34 }; // not 0xFFD8
        ImageInputStream input = ImageIO.createImageInputStream(new ByteArrayInputStream(badPrefix));

        // Act: instantiate the decoder and invoke decode()
        JPEGLosslessDecoder decoder = new JPEGLosslessDecoder(segments, input, null);

        // Assert: an IIOException is thrown with the expected message
        IIOException ex = assertThrows(IIOException.class, () -> decoder.decode(),
                "Expected decode() to throw IIOException when input does not start with SOI (0xFFD8)");
        assertEquals("Not a JPEG file, does not start with 0xFFD8", ex.getMessage(),
                "Error message should indicate missing SOI marker");
    }
}

package com.twelvemonkeys.imageio.plugins.jpeg;

import org.junit.jupiter.api.Test;

import javax.imageio.stream.MemoryCacheImageInputStream;
import java.io.ByteArrayInputStream;
import java.io.EOFException;
import java.io.IOException;
import java.util.Collections;

import static org.junit.jupiter.api.Assertions.assertThrows;

class JPEGLosslessDecoderDecodeTests {
    @Test
    void decodeRejectsTruncatedInputBeforeTheJpegStartMarker() {
        try (MemoryCacheImageInputStream input =
                     new MemoryCacheImageInputStream(new ByteArrayInputStream(new byte[]{(byte) 0xFF}))) {
            JPEGLosslessDecoder decoder =
                    new JPEGLosslessDecoder(Collections.emptyList(), input, null);

            assertThrows(EOFException.class, decoder::decode);
        } catch (IOException e) {
            throw new AssertionError("Unable to close the image input stream", e);
        }
    }
}

