package com.twelvemonkeys.imageio.plugins.pcx;

import org.junit.jupiter.api.Test;

import javax.imageio.ImageReadParam;
import javax.imageio.ImageIO;
import javax.imageio.stream.ImageInputStream;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;

import static org.junit.jupiter.api.Assertions.*;
import javax.imageio.IIOException;

/**
 * PCX ImageReader read() behavior tests.
 * These tests exercise the public PCXImageReader API to validate correct decoding paths and error handling.
 */
public class PCXImageReaderReadTests {

    @Test
    void testRead8BitGrayscaleSingleChannelProducesExpectedPixels() throws Exception {
        // Build a minimal PCX stream (128-byte header, 2x1 image, 2 bytes per line, 8-bit grayscale, 1 channel)
        // Header details:
        // - magic: 0x0A
        // - version: 5 (VERSION_3)
        // - compression: 0 (COMPRESSION_NONE)
        // - bitsPerPixel: 8
        // - XStart: 0, YStart: 0
        // - XEnd: 1, YEnd: 0  -> width=2, height=1
        // - hdpi/vdpi: 0
        // - palette (48 bytes): all zeros
        // - reserved: 0
        // - channels: 1
        // - bytesPerLine: 2 (even)
        // - paletteType: 0
        // - hScreenSize/vScreenSize: 0
        // - rest: zeros
        // Data: two rows (height 1, so one row) with two pixels: [10, 20]
        //        (For height 1, there will be one data row of length 2)
        final int headerSize = PCX.HEADER_SIZE;
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        byte[] header = new byte[headerSize];
        header[0] = PCX.MAGIC;
        header[1] = PCX.VERSION_3;
        header[2] = PCX.COMPRESSION_NONE;
        header[3] = 8; // bitsPerPixel
        // XStart = 0
        header[4] = 0;
        header[5] = 0;
        // YStart = 0
        header[6] = 0;
        header[7] = 0;
        // XEnd = 1
        header[8] = 1;
        header[9] = 0;
        // YEnd = 0 (height = 1)
        header[10] = 0;
        header[11] = 0;
        // hdpi, vdpi
        header[12] = 0;
        header[13] = 0;
        // palette (48 bytes) - leave as zeros
        // header[14..63] already zeros
        // reserved
        header[64] = 0;
        // channels
        header[65] = 1;
        // bytesPerLine (must be even)
        header[66] = 2;
        header[67] = 0;
        // paletteType
        header[68] = 0;
        header[69] = 0;
        // hScreenSize, vScreenSize
        header[70] = 0; header[71] = 0;
        // rest zeros to complete 128-byte header
        for (int i = 72; i < headerSize; i++) {
            header[i] = 0;
        }

        baos.write(header);

        // 1 row of 2 pixels: 10, 20
        baos.write(new byte[]{10, 20});

        ImageInputStream stream = ImageIO.createImageInputStream(new ByteArrayInputStream(baos.toByteArray()));
        PCXImageReaderSpi spi = new PCXImageReaderSpi();
        PCXImageReader reader = new PCXImageReader(spi);
        reader.setInput(stream);

        ImageReadParam param = reader.getDefaultReadParam();
        param.setDestinationType(reader.getImageTypes(0).next());

        BufferedImage image = reader.read(0, param);

        assertNotNull(image, "read() should return a BufferedImage");
        assertEquals(2, image.getWidth(), "Image width should match header width");
        assertEquals(1, image.getHeight(), "Image height should match header height");

        // Expect pixel values to match provided row data in grayscale
        int[] row0 = image.getRaster().getPixels(0, 0, 2, 1, (int[]) null);
        // The getPixels call returns an int[] with all samples for the region; since there are 2 pixels, expect 2 values
        // row0 contains [10, 20]
        assertArrayEquals(new int[]{10, 20}, row0, "Decoded pixel values do not match expected grayscale values");
    }

    @Test
    void testReadThrowsIIOExceptionForTooManyBitPlanes() throws Exception {
        // Build a PCX header that triggers the "Unsupported number of bit planes for PCX" path:
        // - bitsPerPixel: 1 (to encourage IndexColorModel path)
        // - channels: 9 (trigger the 9+ planes error)
        final int headerSize = PCX.HEADER_SIZE;
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        byte[] header = new byte[headerSize];
        header[0] = PCX.MAGIC;
        header[1] = PCX.VERSION_3;
        header[2] = PCX.COMPRESSION_NONE;
        header[3] = 1; // bitsPerPixel = 1
        // XStart = 0
        header[4] = 0;
        header[5] = 0;
        // YStart = 0
        header[6] = 0;
        header[7] = 0;
        // XEnd = 1 -> width = 2
        header[8] = 1;
        header[9] = 0;
        // YEnd = 0 -> height = 1
        header[10] = 0;
        header[11] = 0;
        // hdpi, vdpi
        header[12] = 0;
        header[13] = 0;
        // palette (48 bytes) - leave as zeros
        // reserved
        header[64] = 0;
        // channels = 9 (trigger error)
        header[65] = 9;
        // bytesPerLine
        header[66] = 2; header[67] = 0;
        // paletteType
        header[68] = 0; header[69] = 0;
        // rest zeros
        for (int i = 72; i < headerSize; i++) {
            header[i] = 0;
        }

        baos.write(header);

        // No need to provide image data; the reader should throw during processing
        ImageInputStream stream = ImageIO.createImageInputStream(new ByteArrayInputStream(baos.toByteArray()));
        PCXImageReaderSpi spi = new PCXImageReaderSpi();
        PCXImageReader reader = new PCXImageReader(spi);
        reader.setInput(stream);

        ImageReadParam param = reader.getDefaultReadParam();
        param.setDestinationType(reader.getImageTypes(0).next());

        assertThrows(IIOException.class, () -> {
            reader.read(0, param);
        }, "Expected IIOException due to unsupported number of bit planes (channels > 8)");
    }
}

package com.twelvemonkeys.imageio.plugins.pcx;

import org.junit.jupiter.api.Test;

import javax.imageio.ImageIO;
import javax.imageio.ImageReadParam;
import javax.imageio.stream.ImageInputStream;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;

import static org.junit.jupiter.api.Assertions.assertEquals;

class PCXImageReaderReadTests {
    @Test
    void readsSubsampledSourceRegionWithCorrectPixelAlignment() throws IOException {
        byte[] pcx = createPcx(new int[] {10, 20, 30, 40});

        PCXImageReader reader = new PCXImageReader(null);
        try (ImageInputStream input = ImageIO.createImageInputStream(new ByteArrayInputStream(pcx))) {
            reader.setInput(input);

            ImageReadParam param = reader.getDefaultReadParam();
            param.setSourceRegion(new Rectangle(1, 0, 2, 1));
            param.setSourceSubsampling(2, 1, 0, 0);

            BufferedImage image = reader.read(0, param);

            assertEquals(1, image.getWidth());
            assertEquals(1, image.getHeight());
            assertEquals(10, image.getRaster().getSample(0, 0, 0));
        }
    }

    private static byte[] createPcx(int[] pixels) throws IOException {
        ByteArrayOutputStream output = new ByteArrayOutputStream();

        output.write(0x0A);
        output.write(5);
        output.write(1);
        output.write(8);

        writeLittleEndianShort(output, 0);
        writeLittleEndianShort(output, 0);
        writeLittleEndianShort(output, pixels.length - 1);
        writeLittleEndianShort(output, 0);

        writeLittleEndianShort(output, 72);
        writeLittleEndianShort(output, 72);

        output.write(new byte[48]);
        output.write(0);
        output.write(1);
        writeLittleEndianShort(output, pixels.length);
        writeLittleEndianShort(output, 1);
        writeLittleEndianShort(output, pixels.length);
        writeLittleEndianShort(output, 1);

        while (output.size() < 128) {
            output.write(0);
        }

        for (int pixel : pixels) {
            if (pixel >= 0xC0) {
                output.write(0xC1);
            }
            output.write(pixel);
        }

        return output.toByteArray();
    }

    private static void writeLittleEndianShort(ByteArrayOutputStream output, int value) {
        output.write(value & 0xFF);
        output.write((value >>> 8) & 0xFF);
    }
}

