package com.twelvemonkeys.imageio.plugins.webp.lossless;

import org.junit.jupiter.api.Test;

import java.awt.image.DataBufferByte;
import java.awt.image.Raster;
import java.awt.image.WritableRaster;
import java.awt.Point;

import static org.junit.jupiter.api.Assertions.assertEquals;

public class PredictorTransformApplyInverseTests {

    @Test
    void testApplyInverse_TwoByTwo_LPath() {
        int width = 2;
        int height = 2;

        // Prepare a 2x2 image with 4 channels per pixel in R,G,B,A order.
        // Pixel indexing (x,y):
        // (0,0) (1,0)
        // (0,1) (1,1)
        byte[] imageData = new byte[width * height * 4];

        int idx = 0;
        // (0,0) R,G,B,A
        imageData[idx++] = (byte) 0;   // R
        imageData[idx++] = (byte) 0;   // G
        imageData[idx++] = (byte) 0;   // B
        imageData[idx++] = (byte) 0;   // A

        // (1,0)
        imageData[idx++] = (byte) 10;  // R
        imageData[idx++] = (byte) 20;  // G
        imageData[idx++] = (byte) 30;  // B
        imageData[idx++] = (byte) 40;  // A

        // (0,1)
        imageData[idx++] = (byte) 5;   // R
        imageData[idx++] = (byte) 6;   // G
        imageData[idx++] = (byte) 7;   // B
        imageData[idx++] = (byte) 8;   // A

        // (1,1)
        imageData[idx++] = (byte) 1;   // R
        imageData[idx++] = (byte) 2;   // G
        imageData[idx++] = (byte) 3;   // B
        imageData[idx++] = (byte) 50;  // A

        DataBufferByte imageBuffer = new DataBufferByte(imageData, imageData.length);
        WritableRaster imageRaster = Raster.createInterleavedRaster(imageBuffer, width, height, width * 4,
                4, new int[]{0, 1, 2, 3}, new Point(0, 0));

        // Predictor map (2 bands, band 1 used by the algorithm)
        // We only set (1,1) to 1 to use L path for the inner pixel.
        byte[] predictorData = new byte[width * height * 2];
        // Default 0s
        // (1,1) -> band 1 value = 1
        int innerIndex = (1 * width + 1) * 2;
        predictorData[innerIndex + 0] = 0; // band 0
        predictorData[innerIndex + 1] = 1; // band 1 -> transformType.L

        DataBufferByte predictorBuffer = new DataBufferByte(predictorData, predictorData.length);
        WritableRaster predictorRaster = Raster.createInterleavedRaster(predictorBuffer, width, height, width * 2,
                2, new int[]{0, 1}, new Point(0, 0));

        PredictorTransform transform = new PredictorTransform(predictorRaster, (byte) 0);
        transform.applyInverse(imageRaster);

        // Validate final pixel values according to manual calculation:
        // (0,0) -> (0,0,0,255)
        // (1,0) -> (10,20,30,39)
        // (0,1) -> (5,6,7,7)
        // (1,1) -> (6,8,10,57)

        byte[] pixel = new byte[4];

        imageRaster.getDataElements(0, 0, pixel);
        assertEquals(0, pixel[0] & 0xff, "Pixel (0,0) R");
        assertEquals(0, pixel[1] & 0xff, "Pixel (0,0) G");
        assertEquals(0, pixel[2] & 0xff, "Pixel (0,0) B");
        assertEquals(255, pixel[3] & 0xff, "Pixel (0,0) A");

        imageRaster.getDataElements(1, 0, pixel);
        assertEquals(10, pixel[0] & 0xff, "Pixel (1,0) R");
        assertEquals(20, pixel[1] & 0xff, "Pixel (1,0) G");
        assertEquals(30, pixel[2] & 0xff, "Pixel (1,0) B");
        assertEquals(39, pixel[3] & 0xff, "Pixel (1,0) A");

        imageRaster.getDataElements(0, 1, pixel);
        assertEquals(5, pixel[0] & 0xff, "Pixel (0,1) R");
        assertEquals(6, pixel[1] & 0xff, "Pixel (0,1) G");
        assertEquals(7, pixel[2] & 0xff, "Pixel (0,1) B");
        assertEquals(7, pixel[3] & 0xff, "Pixel (0,1) A");

        imageRaster.getDataElements(1, 1, pixel);
        assertEquals(6, pixel[0] & 0xff, "Pixel (1,1) R");
        assertEquals(8, pixel[1] & 0xff, "Pixel (1,1) G");
        assertEquals(10, pixel[2] & 0xff, "Pixel (1,1) B");
        assertEquals(57, pixel[3] & 0xff, "Pixel (1,1) A");
    }
}

package com.twelvemonkeys.imageio.plugins.webp.lossless;

import org.junit.jupiter.api.Test;

import java.awt.image.DataBuffer;
import java.awt.image.Raster;
import java.awt.image.WritableRaster;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;

class PredictorTransformApplyInverseTests {
    @Test
    void appliesThreePixelAveragePredictorToPixelUsingLeftTopRightAndTop() {
        WritableRaster predictorData = Raster.createInterleavedRaster(
                DataBuffer.TYPE_BYTE,
                3,
                2,
                3 * 4,
                4,
                new int[]{0, 1, 2, 3},
                null
        );

        for (int y = 0; y < predictorData.getHeight(); y++) {
            for (int x = 0; x < predictorData.getWidth(); x++) {
                for (int band = 0; band < predictorData.getNumBands(); band++) {
                    predictorData.setSample(x, y, band, PredictorMode.AVG_L_TR_T);
                }
            }
        }

        WritableRaster raster = Raster.createInterleavedRaster(
                DataBuffer.TYPE_BYTE,
                3,
                2,
                3 * 4,
                4,
                new int[]{0, 1, 2, 3},
                null
        );

        setPixel(raster, 0, 0, 0, 0, 0, 255);
        setPixel(raster, 1, 0, 0, 0, 0, 255);
        setPixel(raster, 2, 0, 90, 0, 0, 255);
        setPixel(raster, 0, 1, 30, 0, 0, 255);
        setPixel(raster, 1, 1, 0, 0, 0, 0);
        setPixel(raster, 2, 1, 0, 0, 0, 255);

        new PredictorTransform(predictorData, (byte) 0).applyInverse(raster);

        assertArrayEquals(new byte[]{30, 0, 0, (byte) 252}, pixel(raster, 1, 1));
    }

    private static void setPixel(WritableRaster raster, int x, int y,
                                 int red, int green, int blue, int alpha) {
        raster.setDataElements(x, y, new byte[]{
                (byte) red,
                (byte) green,
                (byte) blue,
                (byte) alpha
        });
    }

    private static byte[] pixel(Raster raster, int x, int y) {
        return (byte[]) raster.getDataElements(x, y, null);
    }
}

