BoolDecoder(ImageInputStream frame, long offset) throws IOException {
        this.data = frame;
        this.offset = offset;
        initBoolDecoder();
    }

public int readBit() throws IOException {
        return readBool(128);
    }

public int readBool(int probability) throws IOException {
        int bit = 0;
        int split;
        int bigSplit;
        int range = this.range;
        int value = this.value;
        split = 1 + (((range - 1) * probability) >> 8);
        bigSplit = (split << 8);
        range = split;

        if (value >= bigSplit) {
            range = this.range - split;
            value = value - bigSplit;
            bit = 1;
        }

        {
            int count = this.bitCount;
            int shift = Globals.vp8dxBitreaderNorm[range];
            range <<= shift;
            value <<= shift;
            count -= shift;

            if (count <= 0) {
                // data.seek(offset);
                value |= data.readUnsignedByte() << (-count);
                // value |= data[offset] << (-count);
                offset++;
                count += 8;
            }

            this.bitCount = count;
        }
        this.value = value;
        this.range = range;

        return bit;
    }

/**
     * Convenience method reads a "literal", that is, a "numBits" wide
     * unsigned value whose bits come high- to low-order, with each bit encoded
     * at probability 128 (i.e., 1/2).
     */
public int readLiteral(int numBits) throws IOException {
        int v = 0;
        while (numBits-- > 0) {
            v = (v << 1) + readBool(128);
        }

        return v;
    }

public void seek() throws IOException {
        data.seek(offset);
    }

public SegmentQuants() {
        for (int x = 0; x < Globals.MAX_MB_SEGMENTS; x++) {
            segQuants[x] = new SegmentQuant();
        }
    }

public void parse(BoolDecoder bc, boolean segmentation_enabled,
                      boolean mb_segement_abs_delta) throws IOException {
        qIndex = bc.readLiteral(7);
        boolean q_update = false;
        DeltaQ v = get_delta_q(bc, 0);
        int y1dc_delta_q = v.v;
        q_update = q_update || v.update;
        v = get_delta_q(bc, 0);
        int y2dc_delta_q = v.v;
        q_update = q_update || v.update;
        v = get_delta_q(bc, 0);
        int y2ac_delta_q = v.v;
        q_update = q_update || v.update;
        v = get_delta_q(bc, 0);
        int uvdc_delta_q = v.v;
        q_update = q_update || v.update;
        v = get_delta_q(bc, 0);
        int uvac_delta_q = v.v;
        q_update = q_update || v.update;

        for (SegmentQuant s : segQuants) {
            if (!segmentation_enabled) {
                s.setQindex(qIndex);
            }
            else if (!mb_segement_abs_delta) {
                s.setQindex(s.getQindex() + qIndex);
            }

            s.setY1dc(y1dc_delta_q);
            s.setY2dc(y2dc_delta_q);
            s.setY2ac_delta_q(y2ac_delta_q);
            s.setUvdc_delta_q(uvdc_delta_q);
            s.setUvac_delta_q(uvac_delta_q);
        }
    }

private MacroBlock[] createMacroBlockRow(final int mbRow) {
        MacroBlock[] row = new MacroBlock[macroBlockCols + 2];

        for (int mbCol = 0; mbCol < macroBlockCols + 2; mbCol++) {
            row[mbCol] = new MacroBlock(mbCol, mbRow + 1, debug);
        }

        return row;
    }

private void initializeWindowedDecodeState() {
        createMacroBlockMetadata();
        topMacroBlockRow = createMacroBlockRow(-1);
        previousMacroBlockRow = topMacroBlockRow;
        currentMacroBlockRow = null;
        currentMacroBlockRowIndex = -1;
        lastNonBPredMacroBlockByColumn = new MacroBlock[macroBlockCols + 2];

        System.arraycopy(topMacroBlockRow, 0, lastNonBPredMacroBlockByColumn, 0, macroBlockCols + 2);
    }

private void decodeMacroBlockRow(final int mbRow, final WritableRaster raster, final Rectangle region,
                                     final int xSubsampling, final int ySubsampling) throws IOException {
        final boolean filter = filterLevel != 0;

        MacroBlock left = null;
        MacroBlock[] prevRow = previousMacroBlockRow;
        MacroBlock[] currRow = currentMacroBlockRow;

        for (int mbCol = 0; mbCol < macroBlockCols; mbCol++) {
            MacroBlock mb = currRow[mbCol + 1];

            populateMacroBlock(mb, mbRow, mbCol);

            mb.decodeMacroBlock(this);
            mb.dequantMacroBlock(this);

            if (filter) {
                MacroBlock top = mbRow > 0 ? prevRow[mbCol + 1] : null;
                LoopFilter.loopFilterBlock(mb, left, top, frameType, simpleFilter, sharpnessLevel);
            }

            copyBlock(mb, raster, region, xSubsampling, ySubsampling);

            if (mb.getYMode() != Globals.B_PRED) {
                lastNonBPredMacroBlockByColumn[mbCol + 1] = mb;
            }

            left = mb;
        }
    }

private void fireProgressUpdate(int mbRow) {
        if (listener != null) {
            float percentageDone = (100.0f * ((float) (mbRow + 1) / (float) getMacroBlockRows()));
            listener.imageProgress(null, percentageDone);
        }
    }

private int getBitAsInt(int data, int bit) {
        int r = data & (1 << bit);
        if (r != 0) {
            return 1;
        }
        return 0;
    }

private void readModes(BoolDecoder bc) throws IOException {
        int mb_row = -1;
        int prob_skip_false = 0;

        if (macroBlockNoCoeffSkip > 0) {
            prob_skip_false = bc.readLiteral(8);
        }

        while (++mb_row < macroBlockRows) {
            int mb_col = -1;
            while (++mb_col < macroBlockCols) {
                if ((segmentationIsEnabled > 0) && (updateMacroBlockSegmentationMap > 0)) {
                    segmentIds[mb_row][mb_col] = bc.readTree(Globals.macroBlockSegmentTree, this.macroBlockSegmentTreeProbs, 0);
                }

                if (modeRefLoopFilterDeltaEnabled > 0) {
                    int level = filterLevel + refLoopFilterDeltas[0];
                    filterLevels[mb_row][mb_col] = (level < 0) ? 0 : Math.min(level, 63);
                }
                else {
                    filterLevels[mb_row][mb_col] = segmentQuants.getSegQuants()[segmentIds[mb_row][mb_col]].getFilterStrength();
                }

                skipCoeffs[mb_row][mb_col] = macroBlockNoCoeffSkip > 0 ? bc.readBool(prob_skip_false) : 0;

                int yMode = readYMode(bc);
                yModes[mb_row][mb_col] = yMode;

                if (yMode == Globals.B_PRED) {
                    for (int subY = 0; subY < 4; subY++) {
                        for (int subX = 0; subX < 4; subX++) {
                            int aboveMode = getAboveYSubBlockMode(mb_row, mb_col, subX, subY);
                            int leftMode = getLeftYSubBlockMode(mb_row, mb_col, subX, subY);
                            int mode = readSubBlockMode(bc, aboveMode, leftMode);
                            ySubBlockModes[mb_row][mb_col][ySubBlockModeIndex(subX, subY)] = mode;
                        }
                    }

                    if (modeRefLoopFilterDeltaEnabled > 0) {
                        int level = filterLevels[mb_row][mb_col] + this.modeLoopFilterDeltas[0];
                        filterLevels[mb_row][mb_col] = (level < 0) ? 0 : Math.min(level, 63);
                    }
                }
                else {
                    int blockMode;

                    switch (yMode) {
                        case Globals.V_PRED:
                            blockMode = Globals.B_VE_PRED;
                            break;
                        case Globals.H_PRED:
                            blockMode = Globals.B_HE_PRED;
                            break;
                        case Globals.TM_PRED:
                            blockMode = Globals.B_TM_PRED;
                            break;
                        case Globals.DC_PRED:
                        default:
                            blockMode = Globals.B_DC_PRED;
                            break;
                    }

                    for (int subY = 0; subY < 4; subY++) {
                        for (int subX = 0; subX < 4; subX++) {
                            ySubBlockModes[mb_row][mb_col][ySubBlockModeIndex(subX, subY)] = blockMode;
                        }
                    }
                }

                uvModes[mb_row][mb_col] = readUvMode(bc);
            }
        }
    }

private void setupTokenDecoder(BoolDecoder bc, int first_partition_length_in_bytes, long offset) throws IOException {
        long partitionSize;
        long partitionsStart = offset + first_partition_length_in_bytes;
        long partition = partitionsStart;
        multiTokenPartition = bc.readLiteral(2);
        int num_part = 1 << multiTokenPartition;

        if (num_part > 1) {
            partition += 3L * (num_part - 1);
        }
        for (int i = 0; i < num_part; i++) {
            // Calculate the length of this partition. The last partition size is implicit.
            if (i < num_part - 1) {
                partitionSize = readPartitionSize(partitionsStart + (i * 3L));
                bc.seek();
            }
            else {
                partitionSize = frame.length() - partition;
            }

            tokenBoolDecoders.add(new BoolDecoder(frame, partition));
            partition += partitionSize;
        }

        tokenBoolDecoder = tokenBoolDecoders.get(0);
    }

