package com.twelvemonkeys.imageio.plugins.webp.vp8;

import org.junit.jupiter.api.Test;

import javax.imageio.ImageIO;
import javax.imageio.ImageReadParam;
import javax.imageio.stream.ImageInputStream;
import java.awt.image.BufferedImage;
import java.awt.image.WritableRaster;
import java.io.ByteArrayInputStream;
import java.io.IOException;

import static org.junit.jupiter.api.Assertions.*;

public class VP8FrameDecodeTests {

    @Test
    void decodeReturnsFalseForNonIntraFrame() throws IOException {
        // First byte's least significant bit (frameType) is 1 -> non-intra frame
        byte[] data = new byte[]{0x01};
        ImageInputStream iis = ImageIO.createImageInputStream(new ByteArrayInputStream(data));
        assertNotNull(iis, "ImageInputStream should be created");
        VP8Frame frame = new VP8Frame(iis, false);

        BufferedImage img = new BufferedImage(1, 1, BufferedImage.TYPE_INT_RGB);
        WritableRaster raster = img.getRaster();

        boolean result = frame.decode(raster, null);

        assertFalse(result, "decode should return false when frameType != 0 (non-intra frame)");
        // Ensure raster remains unmodified
        int sample = raster.getSample(0, 0, 0);
        assertEquals(0, sample, "Raster should remain unmodified when non-intra frame is encountered");
    }

    @Test
    void decodeThrowsOnInsufficientDataForIntraFrame() throws IOException {
        // frameType 0 (intra frame) but provide insufficient data
        byte[] data = new byte[]{0x00};
        ImageInputStream iis = ImageIO.createImageInputStream(new ByteArrayInputStream(data));
        VP8Frame frame = new VP8Frame(iis, false);

        BufferedImage img = new BufferedImage(1, 1, BufferedImage.TYPE_INT_RGB);
        WritableRaster raster = img.getRaster();

        assertThrows(IOException.class, () -> frame.decode(raster, null));
    }
}

package com.twelvemonkeys.imageio.plugins.webp.vp8;

import org.junit.jupiter.api.Test;

import javax.imageio.ImageReadParam;
import javax.imageio.stream.MemoryCacheImageInputStream;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;

import static org.junit.jupiter.api.Assertions.assertFalse;

class VP8FrameDecodeTests {
    @Test
    void decodeReturnsFalseForInterFrameWithoutProcessingRaster() throws Exception {
        BufferedImage image = new BufferedImage(1, 1, BufferedImage.TYPE_INT_RGB);
        ImageReadParam param = new ImageReadParam();

        try (MemoryCacheImageInputStream stream =
                     new MemoryCacheImageInputStream(new ByteArrayInputStream(new byte[]{0x01}))) {
            VP8Frame frame = new VP8Frame(stream, false);

            assertFalse(frame.decode(image.getRaster(), param));
        }
    }
}
